from(bucket: "metrics-loadtest")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == v.MetricName)
  |> filter(fn: (r) => r["_field"] == "value")
  |> filter(fn: (r) => r["tenant_mode"] == "testing")
  |> group(columns: ["revision", "generation"])
  |> aggregateWindow(
    every: 10s, 
    fn: (column, tables=<-) => tables |> quantile(q: 0.9), 
    createEmpty: true
  )
  |> map(fn: (r) => ({
      r with 
      _value: if r._value > float(v:v.MaxLatency) then float(v:v.MaxLatency) else r._value
    })
  )
  |> yield(name: "p90")

