import "regexp"

pattern = regexp.compile(v: v.AppPodRgx)

from(bucket: "metrics-nodes")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  // 1. 过滤出所有相关的 pod
  |> filter(fn: (r) => r["pod"] =~ /keycloak-\d-\d/)
  |> filter(fn: (r) => r["_measurement"] == "container_spec_memory_limit_bytes")
  |> filter(fn: (r) => r["container"] == v.AppName)

  // 2. 关键步骤：提取前缀并创建新标签 "pod_group"
  // 将 "ppd-demo-1-123" 转换为 "ppd-demo-1"
  |> map(fn: (r) => ({
      r with
      pod_group: regexp.replaceAllString(
          r: /-\d+$/,       // 匹配结尾的横杠加数字
          v: r.pod,         // 原始 pod 名字
          t: ""             // 替换为空，即删除结尾数字
      )
    }))

  // 3. 按照新生成的 pod_group 进行重新分组
  // 此时所有 ppd-demo-1-x 的数据都在一个组里，ppd-demo-2-x 在另一个组里
  |> group(columns: ["pod_group", "_measurement", "_field"])

  // 4. 在每个组（即每个前缀）内进行聚合
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  |> yield(name: "grouped_mean")
